#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking lost"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
nf=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$nf" ] || { echo "not found wrote to stdout: $nf"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 >/dev/null 2>&1; [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
us=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); [ -z "$us" ] || { echo "usage wrote to stdout: $us"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START$' || { echo "usage text missing on stderr"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t13:00\t14:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t2"
out2=$(BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 13:00) || { echo "cancel (same slot, other room) failed"; fail=1; }
[ "$out2" = 'cancelled: aoi 2026-01-05 13:00-14:00 x' ] || { echo "cancel output (same slot): $out2"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t2" || { echo "same slot in another room was deleted"; fail=1; }
rm -f "$t" "$t2"; exit $fail

